entries[21082] = { ["name"] = "Seal of the Crusader", ["text"] = "25 Mana\nInstant\nFills the Paladin with the spirit of a crusader for 30 sec, granting 41 melee attack power. The Paladin also attacks 40% faster, but deals less damage with each attack. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 20 sec, increasing Holy damage taken by up to 23. Your melee strikes will refresh the spell's duration. Only one Judgement per Paladin can be active at any one time." }
entries[21084] = { ["name"] = "Seal of Righteousness", ["text"] = "20 Mana\nInstant\nFills the Paladin with holy spirit for 30 sec, granting each melee attack an additional [1.2 * ( 216 * 1.2 * 1.03 * Mainhand weapon max base speed / 100) + 0.03 * (Mainhand weapon max damage + Mainhand weapon min damage) / 2 + 1] Holy damage. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will cause 26 Holy damage to an enemy." }
